    if fac_red[fid]>float(facs[fid]['red_capacity_kg'])+1e-9:
        viol.append(('fac_red',fid,round(fac_red[fid],1),f'<= {facs[fid][\"red_capacity_kg\"]}'))
    if fac_yellow[fid]>float(facs[fid]['yellow_capacity_kg'])+1e-9:
        viol.append(('fac_yellow',fid,round(fac_yellow[fid],1),f'<= {facs[fid][\"yellow_capacity_kg\"]}'))
    if fac_total[fid]>0 and fac_total[fid]<float(config['minimum_facility_throughput_kg'])-1e-9:
        viol.append(('fac_min_throughput',fid,round(fac_total[fid],1),f'>= {config[\"minimum_facility_throughput_kg\"]}'))
