if len(used_facilities)>int(config['max_open_facilities']):
    viol.append(('max_open_facilities',len(used_facilities),f'<= {config[\"max_open_facilities\"]}'))
for (fid,wid),n in sorted(window_usage.items()):
    w=[w for w in windows[fid] if w['window_id']==wid][0]
    kg=window_kg[(fid,wid)]
    print('WIN',fid,wid,'unloads',n,'kg',round(kg,1),'caps',w['max_unloads'],w['max_kg'])
    if n>int(w['max_unloads']):
        viol.append(('win_unloads',f'{fid}|{wid}',n,f'<= {w[\"max_unloads\"]}'))
    if kg>float(w['max_kg'])+1e-9:
        viol.append(('win_kg',f'{fid}|{wid}',round(kg,1),f'<= {w[\"max_kg\"]}'))

